-- TEST DATA ONLY. Generated by supabase/demo/gen_demo_sites.mjs; do not edit by hand.
-- Re-seeds the demo sites (gunjan) with the website-v2 starter content and links
-- their agents to the demo company 'demo-life' (approved). Run as postgres in the SQL Editor AFTER
-- 20261017132241_companies_offers.sql, 20261018073025_catalog_sync.sql and supabase/demo/demo_offers.sql.
-- Idempotent. Keeps each site's contact section, hero photo and designation (they never leave the database).
begin;

-- Company links: a pending request, then approved (the memberships guard only allows that path).
insert into public.company_memberships (agent_id, company_id)
select s.agent_id, c.id
  from public.sites s
  join public.companies c on c.slug = 'demo-life'
 where s.slug in ('gunjan') and s.deleted_at is null
   and not exists (select 1 from public.company_memberships m
                    where m.agent_id = s.agent_id and m.status in ('pending', 'approved'));
update public.company_memberships m
   set status = 'approved'
  from public.sites s, public.companies c
 where s.slug in ('gunjan') and s.deleted_at is null
   and c.slug = 'demo-life' and m.agent_id = s.agent_id and m.company_id = c.id and m.status = 'pending';

-- gunjan: spotlight (offers), en
update public.sites s
   set template_key = 'spotlight',
       accent = 'maroon',
       locale = 'en',
       draft_content = v.content,
       published_content = v.content,
       published_at = now()
  from (select s2.id,
               '{"hero":{"headline":"Hi, I''m Gunjan","subheadline":"Planning your family''s future? Let''s find cover that fits your needs and budget. I''m with you from the first question to the claim."},"about":{"bio":"Hello, I''m Gunjan, and my work is helping families feel secure about tomorrow. Whether you''re buying your first policy, planning your child''s education or thinking about retirement, I''ll explain your choices clearly and help you decide with confidence. No jargon, no pressure, just honest guidance.","languagesSpoken":["english"]},"services":{"offered":["term","endowment","child","pension","health"],"items":[{"interest":"term","description":"High cover at a low premium, so your family stays financially secure if something happens to you."},{"interest":"endowment","description":"Protection and regular saving in one plan, with a benefit at maturity as per the policy terms."},{"interest":"child","description":"Plan ahead for your child''s education and milestones, with cover that keeps the plan going even if you''re not there."},{"interest":"pension","description":"Build a regular income for retirement, so you stay independent and comfortable in your later years."},{"interest":"health","description":"Cover for hospital bills and medical emergencies for you and your family, so your savings stay safe."}]},"highlights":{"items":[{"icon":"support_agent","title":"Personal guidance","text":"Advice shaped around your family, your goals and your budget."},{"icon":"schedule","title":"Timely reminders","text":"No missed premiums: you''ll hear from me well before each due date."},{"icon":"handshake","title":"Honest advice","text":"No pressure and no jargon, just clear answers you can trust."},{"icon":"verified_user","title":"Help with claims","text":"Forms, documents and follow-ups: I help with the whole claim process."}]},"faq":{"items":[{"question":"How much life cover do I need?","answer":"There''s no single number. I look at what your family would need to keep going, such as daily expenses, loans and children''s studies, and at what you already have. Then we choose cover that fits your budget."},{"question":"What is the difference between term insurance and a savings plan?","answer":"Term insurance pays only if something happens to you during the policy term, so a large cover costs a low premium. A savings plan combines protection with saving and pays a benefit at maturity as per its terms, but costs more for the same cover. I''ll explain both and help you choose."},{"question":"Which documents do I need to buy a policy?","answer":"Usually a photo ID and address proof (such as Aadhaar, PAN, passport or voter ID), a recent photograph, income proof for higher cover, and your bank details. Some plans also need a medical check-up. I''ll give you the exact list for the plan you choose."},{"question":"How can I pay my premium?","answer":"Yearly, half-yearly, quarterly or monthly: pick what fits your budget. You can pay online, set up auto-debit or pay at a branch. I keep track of your due dates and remind you in time. Any tax benefit applies as per prevailing tax laws."},{"question":"Will you help with claims?","answer":"Of course. A claim is when you need support the most. I''ll explain what''s needed, help you fill in the forms, gather the documents with you and follow up until you have an answer."}]},"sectionOrder":["hero","offers","services","highlights","about","testimonials","achievements","faq","contact"],"hidden":["achievements","testimonials"]}'::jsonb
               || jsonb_build_object('contact', coalesce(s2.published_content -> 'contact', s2.draft_content -> 'contact', '{}'::jsonb))
               || jsonb_build_object('hero', ('{"headline":"Hi, I''m Gunjan","subheadline":"Planning your family''s future? Let''s find cover that fits your needs and budget. I''m with you from the first question to the claim."}'::jsonb)
                    || jsonb_strip_nulls(jsonb_build_object('photo', s2.published_content #> '{hero,photo}')))
               || jsonb_build_object('about', ('{"bio":"Hello, I''m Gunjan, and my work is helping families feel secure about tomorrow. Whether you''re buying your first policy, planning your child''s education or thinking about retirement, I''ll explain your choices clearly and help you decide with confidence. No jargon, no pressure, just honest guidance.","languagesSpoken":["english"]}'::jsonb)
                    || jsonb_strip_nulls(jsonb_build_object('designation', s2.published_content #> '{about,designation}')))
               as content
          from public.sites s2
         where s2.slug = 'gunjan' and s2.deleted_at is null) v
 where s.id = v.id;

commit;

-- Check (public data only): both sites render with offers and no company name.
select s.slug, s.template_key,
       jsonb_array_length(coalesce(public.get_public_site(s.slug) #> '{offers,items}', '[]'::jsonb)) as offers,
       public.get_public_site(s.slug) -> 'company' as company
  from public.sites s where s.slug in ('gunjan');
